(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.DomainRangeLesson,num=window.LinearLesson,ns='http://www.w3.org/2000/svg';
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function input(){const rule=$('[name="domain-rule"]:checked').value,x=Number($('#domain-input').value),ok=core.allowed(rule,x);$('#input-output').value=x;let tex,feedback,domain;if(rule==='reciprocal'){domain='D=(-\\infty,1)\\cup(1,\\infty)';tex=ok?`\\frac1{(${x})-1}=${num.fractionTex(num.rational(1,x-1))}`:'\\frac1{1-1}=\\frac10\\quad\\text{tidak terdefinisi}';feedback=ok?'Masukan ini diperbolehkan: penyebutnya bukan nol.':'Masukan satu tidak diperbolehkan karena membuat penyebut nol. Hasilnya tidak dapat dinyatakan sebagai bilangan real; pembagian dengan nol tidak terdefinisi.';}else if(rule==='root'){domain='D=[2,\\infty)';const inside=x-2;tex=ok?`\\sqrt{${x}-2}=\\sqrt{${inside}}`:`\\sqrt{(${x})-2}=\\sqrt{${inside}}`;if(ok&&Number.isInteger(Math.sqrt(inside)))tex+='='+Math.sqrt(inside);feedback=ok?'Masukan ini diperbolehkan: isi akar tidak negatif. Akar nol juga diperbolehkan.':'Masukan ini tidak diperbolehkan dalam bilangan real karena isi akar negatif.';}else{domain='D=\\mathbb R';tex=`(${x})^2=${x*x}`;feedback='Masukan ini diperbolehkan. Bilangan negatif, nol, dan positif semuanya dapat dikuadratkan.';}math($('#input-evaluation'),tex);math($('#rule-domain'),domain);$('#input-feedback').textContent=feedback;}
document.querySelectorAll('[name="domain-rule"]').forEach(e=>e.addEventListener('change',input));$('#domain-input').addEventListener('input',input);input();
function svg(tag,attrs,parent){const e=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e;}
function tick(n,left,top){const e=document.createElement('span');e.className='domain-tick';e.dataset.noEquation='';e.textContent=String(n).replace('-','−');e.style.left=left+'%';e.style.top=top+'%';$('#plot-labels').append(e);}
for(let x=-3;x<=3;x++){const p=core.point(x,0);svg('line',{x1:p.x,x2:p.x,y1:40,y2:310},$('#domain-grid'));tick(x,p.x/3.6,90);}
for(let y=1;y<=9;y++){const p=core.point(0,y);svg('line',{x1:60,x2:300,y1:p.y,y2:p.y},$('#domain-grid'));tick(y,54,p.y/3.6);}
const configs={all:{a:-3,b:3,open:false,domain:'\\mathbb R',range:'[0,\\infty)',description:'Domainnya semua bilangan real. Range-nya semua bilangan real yang tidak negatif. Kuadrat mencapai nol dan tidak memiliki batas atas.'},cross:{a:-2,b:3,open:false,domain:'[-2,3]',range:'[0,9]',description:'Range-nya dari nol sampai sembilan, termasuk kedua batas. Nol dicapai di dalam domain, bukan pada kedua ujungnya.'},closed:{a:1,b:3,open:false,domain:'[1,3]',range:'[1,9]',description:'Range-nya dari satu sampai sembilan, termasuk kedua batas. Masukan satu menghasilkan satu dan masukan tiga menghasilkan sembilan.'},open:{a:1,b:3,open:true,domain:'(1,3]',range:'(1,9]',description:'Range-nya lebih dari satu sampai sembilan. Keluaran satu tidak tercapai karena masukan satu dikecualikan dan masukan negatif satu juga tidak berada dalam domain.'}};
function plot(){const key=$('[name="domain-case"]:checked').value,c=configs[key],range=key==='all'?{min:0,max:9,minIncluded:true,maxIncluded:false}:core.squareRange(c.a,c.b,c.open,false),commands=[];for(let i=0;i<=100;i++){const x=c.a+(c.b-c.a)*i/100,p=core.point(x,x*x);commands.push(`${i===0?'M':'L'}${p.x} ${p.y}`);}$('#square-curve').setAttribute('d',commands.join(' '));const left=core.point(c.a,0).x,right=core.point(c.b,0).x,bottom=core.point(0,range.min).y,top=core.point(0,range.max).y;$('#domain-projection').setAttribute('d',`M${left} 338H${right}`+(key==='all'?` M${left+6} 332L${left} 338L${left+6} 344 M${right-6} 332L${right} 338L${right-6} 344`:''));$('#range-projection').setAttribute('d',`M154 ${bottom}V${top}`+(key==='all'?` M148 ${top+6}L154 ${top}L160 ${top+6}`:''));$('#endpoints').replaceChildren();function dot(x,y,included,color){svg('circle',{cx:x,cy:y,r:4,fill:included?color:'#fafaf5',stroke:color},$('#endpoints'));}if(key!=='all'){for(const [x,included] of [[c.a,!c.open],[c.b,true]]){const p=core.point(x,x*x);dot(p.x,p.y,included,'#244d40');}dot(left,338,!c.open,'#b4754f');dot(right,338,true,'#b4754f');dot(154,top,range.maxIncluded,'#7d6591');}dot(154,bottom,range.minIncluded,'#7d6591');math($('#sets-result'),`D=${c.domain}\\qquad R_f=${c.range}`);$('#range-feedback').textContent=c.description;$('#domain-plot').setAttribute('aria-label','Grafik kuadrat dengan domain '+({all:'semua bilangan real',cross:'negatif dua sampai tiga, kedua batas termasuk',closed:'satu sampai tiga, kedua batas termasuk',open:'lebih dari satu sampai tiga, tiga termasuk'})[key]+'. '+c.description);$('#plot-note').textContent=key==='all'?'Grafik ini hanya menampilkan masukan dari negatif tiga sampai tiga dan keluaran sampai sembilan. Kurva berlanjut di luar jendela; panah proyeksi menunjukkan himpunan yang tidak terbatas.':'Kedua ujung bagian grafik ditunjukkan seluruhnya. Garis jingga dan ungu adalah proyeksi himpunan, bukan tambahan pada grafik fungsi.';}
document.querySelectorAll('[name="domain-case"]').forEach(e=>e.addEventListener('change',plot));plot();
const questions=[{tex:'f(x)=\\frac1{x-2}',prompt:'Tanpa pembatasan lain, apa domain real terbesar fungsi ini?',options:['Semua bilangan real selain dua.','Semua bilangan real selain nol.','Semua bilangan real.'],answer:0,why:'Penyebut nol saat masukan dua. Nilai lainnya sah, termasuk nol.'},{tex:'g(x)=\\sqrt{x+1}',prompt:'Apa domain real terbesar fungsi ini?',options:['Lebih besar dari negatif satu, tanpa batasnya.','Lebih besar dari atau sama dengan negatif satu.','Lebih kecil dari atau sama dengan negatif satu.'],answer:1,why:'Isi akar harus tidak negatif. Masukan negatif satu menghasilkan akar nol, sehingga batas itu ikut.'},{tex:'f(x)=x^2,\\quad D=[-2,3]',prompt:'Apa range fungsi dengan domain ini?',options:['Dari empat sampai sembilan, kedua batas termasuk.','Dari negatif dua sampai tiga, kedua batas termasuk.','Dari nol sampai sembilan, kedua batas termasuk.'],answer:2,why:'Masukan nol berada di dalam domain dan menghasilkan keluaran minimum nol. Nilai maksimum sembilan dicapai pada tiga.'},{tex:'f(x)=x^2,\\quad D=(1,3]',prompt:'Apa range fungsi dengan domain ini?',options:['Dari satu sampai sembilan, kedua batas termasuk.','Lebih dari satu sampai sembilan, sembilan termasuk.','Dari nol sampai sembilan, kedua batas termasuk.'],answer:1,why:'Masukan satu dikecualikan, sehingga keluaran satu tidak tercapai. Sembilan tetap tercapai pada masukan tiga.'},{tex:'h(x)=\\frac1{x-1}',prompt:'Dengan domain semua bilangan real selain satu, keluaran mana yang tidak mungkin?',options:['Nol.','Negatif satu.','Satu.'],answer:0,why:'Pecahan dengan pembilang satu tidak dapat bernilai nol. Negatif satu tercapai pada masukan nol, dan satu tercapai pada masukan dua.'},{tex:'f(x)=x^2,\\quad D=\\{-1,0,2\\}',prompt:'Jika kodomainnya semua bilangan real, apa range fungsi ini?',options:['Semua bilangan real.','Hanya nol, satu, dan empat.','Semua bilangan dari nol sampai empat.'],answer:1,why:'Domain hanya berisi tiga masukan. Keluaran yang muncul hanya nol, satu, dan empat; nilai di antaranya belum tentu tercapai.'}];
const solved=new Set();$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((text,k)=>`<label class="choice"><input name="answer${i}" type="radio" value="${k}">${text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('[data-check]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.check),q=questions[i],a=$(`[name="answer${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer,e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}));
const storage={get(k){try{return localStorage.getItem('fondasi-domain-range-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-domain-range-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();